#!/usr/bin/env node

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.dirname(fileURLToPath(import.meta.url));
const SITE_VERSION = "v202";

const homepageBase64 = "";
const termsBase64 = "";
const beatTemplateBase64 = "";

const decode = (value) => Buffer.from(value, "base64").toString("utf8");

const homepage = decode(homepageBase64).replaceAll(
  "__SITE_VERSION__",
  SITE_VERSION,
);
const termsPage = decode(termsBase64);
const beatTemplate = decode(beatTemplateBase64);

fs.writeFileSync(path.join(root, "index.html"), homepage);
fs.writeFileSync(path.join(root, "terms.html"), termsPage);

const beatPattern =
  /\{\s*id:\s*"([^"]+)",\s*title:\s*"([^"]+)",\s*bpm:\s*(\d+),\s*key:\s*"([^"]+)",\s*tags:\s*\[([^\]]*)\][\s\S]*?audioSrc:\s*"([^"]+)"/g;

const beats = [];
for (const match of homepage.matchAll(beatPattern)) {
  beats.push({
    id: match[1],
    title: match[2],
    bpm: Number(match[3]),
    key: match[4],
    tags: JSON.parse(`[${match[5]}]`),
    audioSrc: match[6],
    slug: match[6].replace(/\.mp3$/i, ""),
  });
}

if (beats.length !== 24) {
  throw new Error(`Expected 24 beats in the homepage, found ${beats.length}.`);
}

const escapeHtml = (value) =>
  String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#x27;");

for (const beat of beats) {
  const escapedTitle = escapeHtml(beat.title);
  const tagSummary = beat.tags.join(", ");
  const tagJson = beat.tags.map((tag) => JSON.stringify(tag)).join(", ");
  const tagHtml = beat.tags
    .map((tag) => `<span class="tag mono">${escapeHtml(tag)}</span>`)
    .join("");

  const page = beatTemplate
    .replaceAll("Po&#x27; Man&#x27;s Dreams", escapedTitle)
    .replaceAll("Po' Man's Dreams", beat.title)
    .replaceAll("po-mans-dreams", beat.slug)
    .replaceAll("dark, angelic", tagSummary)
    .replaceAll('"dark", "angelic"', tagJson)
    .replaceAll(
      '<span class="tag mono">dark</span><span class="tag mono">angelic</span>',
      tagHtml,
    )
    .replaceAll("85 BPM", `${beat.bpm} BPM`)
    .replaceAll("85 bpm", `${beat.bpm} bpm`)
    .replaceAll("A min", beat.key);

  const outputDir = path.join(root, "beats", beat.slug);
  fs.mkdirSync(outputDir, { recursive: true });
  fs.writeFileSync(path.join(outputDir, "index.html"), page);
}

const deployInfo = {
  commit: process.env.COMMIT_REF || "",
  build_id: process.env.BUILD_ID || "",
  context: process.env.CONTEXT || "local",
  deployed_at: new Date().toISOString(),
};
fs.writeFileSync(
  path.join(root, "deploy.json"),
  `${JSON.stringify(deployInfo)}\n`,
);

console.log(
  `Built homepage, terms page, and ${beats.length} beat pages from site-source.mjs (${SITE_VERSION}).`,
);
